  'reg.title': { en: 'Register this phone', hi: 'यह फ़ोन पंजीकृत करें', pa: 'ਇਹ ਫ਼ੋਨ ਰਜਿਸਟਰ ਕਰੋ' },
  'reg.hint': { en: 'Show this QR to the agriculture officer once. Only registered phones are paid.', hi: 'यह QR एक बार कृषि अधिकारी को दिखाएँ। केवल पंजीकृत फ़ोन का भुगतान होता है।', pa: 'ਇਹ QR ਇੱਕ ਵਾਰ ਖੇਤੀਬਾੜੀ ਅਧਿਕਾਰੀ ਨੂੰ ਦਿਖਾਓ। ਸਿਰਫ਼ ਰਜਿਸਟਰਡ ਫ਼ੋਨਾਂ ਦਾ ਭੁਗਤਾਨ ਹੁੰਦਾ ਹੈ।' },
  'reg.show': { en: 'Show registration QR', hi: 'पंजीकरण QR दिखाएँ', pa: 'ਰਜਿਸਟਰੇਸ਼ਨ QR ਦਿਖਾਓ' },
  'reg.modal_hint': { en: 'Signed by this phone’s own key. It holds the key, its id and your CHC label — no phone number.', hi: 'इसी फ़ोन की कुंजी से हस्ताक्षरित। इसमें कुंजी, उसका id और CHC नाम है — फ़ोन नंबर नहीं।', pa: 'ਇਸੇ ਫ਼ੋਨ ਦੀ ਕੁੰਜੀ ਨਾਲ ਦਸਤਖ਼ਤੀ। ਇਸ ਵਿੱਚ ਕੁੰਜੀ, ਉਸ ਦਾ id ਅਤੇ CHC ਨਾਂ ਹੈ — ਫ਼ੋਨ ਨੰਬਰ ਨਹੀਂ।' },
