  'ui.demo_short': { en: 'Demo', hi: 'डेमो', pa: 'ਡੈਮੋ' },
  'tour.s8': { en: 'A person decides: “Needs visit”, with a reason, signed into a log that can only grow.', hi: 'फ़ैसला व्यक्ति करता है: “दौरा ज़रूरी”, कारण सहित, ऐसे लॉग में हस्ताक्षरित जो सिर्फ़ बढ़ सकता है।', pa: 'ਫ਼ੈਸਲਾ ਵਿਅਕਤੀ ਕਰਦਾ ਹੈ: “ਦੌਰਾ ਜ਼ਰੂਰੀ”, ਕਾਰਨ ਸਮੇਤ, ਅਜਿਹੇ ਲੌਗ ਵਿੱਚ ਦਸਤਖ਼ਤੀ ਜੋ ਸਿਰਫ਼ ਵਧ ਸਕਦਾ ਹੈ।' },
  'tour.s9': { en: 'Only ready claims reach the district committee. It approves the batch and signs the minutes; the HQ payment file is ready.', hi: 'सिर्फ़ तैयार दावे ज़िला समिति तक पहुँचते हैं। समिति बैच स्वीकृत करके कार्यवृत्त पर हस्ताक्षर करती है; HQ भुगतान फ़ाइल तैयार है।', pa: 'ਸਿਰਫ਼ ਤਿਆਰ ਦਾਅਵੇ ਜ਼ਿਲ੍ਹਾ ਕਮੇਟੀ ਤੱਕ ਪਹੁੰਚਦੇ ਹਨ। ਕਮੇਟੀ ਬੈਚ ਮਨਜ਼ੂਰ ਕਰਕੇ ਕਾਰਵਾਈ ਉੱਤੇ ਦਸਤਖ਼ਤ ਕਰਦੀ ਹੈ; HQ ਭੁਗਤਾਨ ਫ਼ਾਈਲ ਤਿਆਰ ਹੈ।' },
  'tour.intro_title': { en: 'See ParaliProof work', hi: 'ParaliProof को काम करते देखें', pa: 'ParaliProof ਨੂੰ ਕੰਮ ਕਰਦੇ ਦੇਖੋ' },
  'tour.intro_body': { en: 'A tractor job becomes a signed certificate; an officer checks it in seconds, offline; then the district committee approves it.', hi: 'ट्रैक्टर का काम हस्ताक्षरित प्रमाणपत्र बनता है; अधिकारी सेकंडों में, बिना इंटरनेट, जाँचता है; फिर ज़िला समिति स्वीकृत करती है।', pa: 'ਟਰੈਕਟਰ ਦਾ ਕੰਮ ਦਸਤਖ਼ਤੀ ਸਰਟੀਫਿਕੇਟ ਬਣਦਾ ਹੈ; ਅਧਿਕਾਰੀ ਸਕਿੰਟਾਂ ਵਿੱਚ, ਬਿਨਾਂ ਇੰਟਰਨੈੱਟ, ਜਾਂਚਦਾ ਹੈ; ਫਿਰ ਜ਼ਿਲ੍ਹਾ ਕਮੇਟੀ ਮਨਜ਼ੂਰ ਕਰਦੀ ਹੈ।' },
  'tour.start': { en: 'Start the demo', hi: 'डेमो शुरू करें', pa: 'ਡੈਮੋ ਸ਼ੁਰੂ ਕਰੋ' },
  'judge.card_title': { en: 'Judging, or just looking? See it work in 2 minutes', hi: 'जज हैं या बस देख रहे हैं? 2 मिनट में काम करते देखें', pa: 'ਜੱਜ ਹੋ ਜਾਂ ਬੱਸ ਦੇਖ ਰਹੇ ਹੋ? 2 ਮਿੰਟਾਂ ਵਿੱਚ ਕੰਮ ਕਰਦੇ ਦੇਖੋ' },
  'judge.card_meta': { en: 'Sample data. Nothing is saved.', hi: 'नमूना डेटा। कुछ भी सेव नहीं होता।', pa: 'ਨਮੂਨਾ ਡਾਟਾ। ਕੁਝ ਵੀ ਸੇਵ ਨਹੀਂ ਹੁੰਦਾ।' },
  'off.note': { en: 'Offline · everything still works', hi: 'ऑफ़लाइन · सब कुछ चलता रहता है', pa: 'ਆਫ਼ਲਾਈਨ · ਸਭ ਕੁਝ ਚੱਲਦਾ ਰਹਿੰਦਾ ਹੈ' },
  'off.title': { en: 'No signal? Keep working.', hi: 'सिग्नल नहीं? काम जारी रखें।', pa: 'ਸਿਗਨਲ ਨਹੀਂ? ਕੰਮ ਜਾਰੀ ਰੱਖੋ।' },
  'off.body': { en: 'Recording, signing and checking certificates all work without signal. Map pictures need internet; the measurement does not.', hi: 'रिकॉर्ड करना, हस्ताक्षर और प्रमाणपत्र जाँचना बिना सिग्नल के चलता है। नक्शे की तस्वीरों को इंटरनेट चाहिए; माप को नहीं।', pa: 'ਰਿਕਾਰਡ ਕਰਨਾ, ਦਸਤਖ਼ਤ ਅਤੇ ਸਰਟੀਫਿਕੇਟ ਜਾਂਚਣਾ ਬਿਨਾਂ ਸਿਗਨਲ ਦੇ ਚੱਲਦਾ ਹੈ। ਨਕਸ਼ੇ ਦੀਆਂ ਤਸਵੀਰਾਂ ਨੂੰ ਇੰਟਰਨੈੱਟ ਚਾਹੀਦਾ ਹੈ; ਮਾਪ ਨੂੰ ਨਹੀਂ।' },
